             this.video.playbackRate = Math.max(0.85, 1.0 - Math.abs(errorFactor) * 0.2);
        } else {
             this.video.playbackRate = 1.0;
        }

        this.speedControl.value = Math.max(0.5, Math.min(maxSpeed, targetSpeed));
        this.updateRangeValue('speed');
    }
}
```

#### Versão 2: Limitação Dinâmica de Aceleração (Safety First)
Garante que a velocidade de aceleração seja limitada e só aumente se o sistema estiver abaixo de um limite seguro, prevenindo picos de processamento.

```javascript
// ... (cálculos de timeDifference e maxSpeed)
if (timeDifference < 500 && maxSpeed > 1.2) { 
    // Aceleração controlada em pequenos incrementos, mas verifica o limite
