// ... (restante da lógica)
```

#### Versão 3: Pré-sincronização Preditiva
Em vez de reagir apenas quando o evento está *atrasado* (timeDifference < 500), ajusta a velocidade *antes* que o atraso ocorra, usando uma janela de antecipação (e.g., 1500ms).

```javascript
adjustSynchronization(currentTime) {
    if (this.speechQueue.length > 0 && this.dubbingMode === 'advanced') {
        const timeDifference = this.speechQueue[0].startTime - currentTime;
        const maxSpeed = parseFloat(this.maxSpeedControl.value);

        if (timeDifference < 1500 && timeDifference > -300) { // Janela preditiva
            // Ajusta suavemente para a velocidade máxima se estiver entrando na janela de atraso
            this.speedControl.value = Math.min(maxSpeed, 1.2 + (1500 - timeDifference) / 1000 * (maxSpeed - 1.2));
        } else if (timeDifference > 1000) {
            // Apenas retoma o padrão se estiver bem adiantado
            this.speedControl.value = 1.2;
        }
        // ... (atualização de vídeo)
        this.updateRangeValue('speed');
    }
}
```

#### Versão 4: Prioridade de Sincronia (Otimização de Erro)
O foco primário é zerar o `timeDifference`. A velocidade máxima deve ser usada apenas como ferramenta para atingir a sincronia, não como um alvo fixo.

```javascript
adjustSynchronization(currentTime) {
    if (this.speechQueue.length > 0 && this.dubbingMode === 'advanced') {
        const timeDifference = this.speechQueue[0].startTime - currentTime;
        let targetSpeed = 1.2;

        if (Math.abs(timeDifference) > 100) {
            // Calcula a velocidade necessária para compensar o erro (erro / tempo)
            // Ex: Se 500ms atrasado, a velocidade deve ser 1.2 + (0.5/1.2) ≈ 1.41
            targetSpeed = 1.2 + (Math.abs(timeDifference) / 1000) * 0.5; 
        }

        // Garante que a velocidade nunca ultrapasse o máximo definido
        targetSpeed = Math.min(targetSpeed, parseFloat(this.maxSpeedControl.value));

        this.speedControl.value = targetSpeed;
        // ... (ajuste de vídeo)
        this.updateRangeValue('speed');
    }
}
```

#### Versão 5: Gestão de Estado (Transição Limpa)
Adiciona um estado interno (e.g., `isSyncAdjusting`) para evitar ajustes múltiplos e concorrentes enquanto uma correção já está em andamento.

```javascript
// Assumindo que 'this.isSyncAdjusting' existe e é boolean
adjustSynchronization(currentTime) {
    if (this.speechQueue.length === 0 || !this.dubbingMode === 'advanced') return;

    if (this.isSyncAdjusting) return; // Evita sobreposição de ajustes

    const timeDifference = this.speechQueue[0].startTime - currentTime;
    this.isSyncAdjusting = true; // Entra no estado de ajuste

    try {
        // Lógica de ajuste original ou aprimorada...
        if (timeDifference < 500) { 
            this.speedControl.value = parseFloat(this.maxSpeedControl.value);
        } else if (timeDifference > 1000) { 
            this.speedControl.value = 1.2;
        } else {
            this.speedControl.value = this.userConfiguredSpeed;
        }
        // ... (ajuste de vídeo)
        this.updateRangeValue('speed');
    } finally {
        // Sair do estado de ajuste após a execução
        this.isSyncAdjusting = false; 
    }
}
```

#### Versão 6: Inteligência Contextual (Verifica Limites Antes de Mudar)
Evita tentar aumentar a velocidade se já estiver no máximo, ou diminuir se já estiver no mínimo, otimizando a execução.

```javascript
adjustSynchronization(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const timeDifference = this.speechQueue[0].startTime - currentTime;
    const maxSpeed = parseFloat(this.maxSpeedControl.value);
    const currentSpeed = parseFloat(this.speedControl.value);

    if (timeDifference < 500) { 
        // Só aumenta se não estiver no máximo
        if (currentSpeed < maxSpeed) {
            this.speedControl.value = Math.min(maxSpeed, currentSpeed + 0.1);
        }
    } else if (timeDifference > 1000) { 
        // Só diminui se não estiver no padrão (1.2) ou abaixo
        if (currentSpeed > 1.2) {
            this.speedControl.value = Math.max(1.2, currentSpeed - 0.1);
        }
    } else {
        // Sincronizado
        this.speedControl.value = this.userConfiguredSpeed;
    }
    // ... (ajuste de vídeo)
    this.updateRangeValue('speed');
}
```

#### Versão 7: Foco em Baixa Latência (Threshold Reduzido)
Reduz os limites de erro (500ms -> 300ms, 1000ms -> 600ms) para uma resposta mais imediata a desvios pequenos, ideal para ambientes de baixa latência.

```javascript
adjustSynchronization(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const timeDifference = this.speechQueue[0].startTime - currentTime;
    const maxSpeed = parseFloat(this.maxSpeedControl.value);

    if (timeDifference < 300) { // Mais sensível: Dublagem muito atrasada
        this.speedControl.value = maxSpeed;
        // ... (lógica de vídeo)
    } else if (timeDifference > 600) { // Mais sensível: Dublagem adiantada
        this.speedControl.value = 1.2;
        // ... (lógica de vídeo)
    } else {
        this.speedControl.value = this.userConfiguredSpeed;
        // ... (lógica de vídeo)
    }
    this.updateRangeValue('speed');
}
```

#### Versão 8: Suavização Exponencial
Em vez de ajustes lineares, usamos uma suavização exponencial (ou *lerp* - interpolação linear) para que a velocidade se aproxime gradualmente do alvo, sem saltos bruscos.

```javascript
// Assumindo uma função lerp(a, b, t)
adjustSynchronization(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const timeDifference = this.speechQueue[0].startTime - currentTime;
    const maxSpeed = parseFloat(this.maxSpeedControl.value);

    let targetSpeed = 1.2;
    if (timeDifference < 500) { targetSpeed = maxSpeed; } 
    else if (timeDifference > 1000) { targetSpeed = 1.2; }
    else { targetSpeed = this.userConfiguredSpeed; }

    // Aplica o suavizador (e.g., 0.1 de taxa de transição)
    const currentSpeed = parseFloat(this.speedControl.value);
    this.speedControl.value = currentSpeed + (targetSpeed - currentSpeed) * 0.1; 

    // ... (ajuste de vídeo)
    this.updateRangeValue('speed');
}
```

#### Versão 9: Fallback Inteligente (Tratamento de Erros)
Verifica se `maxSpeed` é válido antes de usá-lo e estabelece um fallback seguro (e.g., 1.2x) se o controle de velocidade falhar ou for inválido.

```javascript
adjustSynchronization(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const timeDifference = this.speechQueue[0].startTime - currentTime;
    // Verifica a validade do controle
    const maxSpeed = parseFloat(this.maxSpeedControl.value);
    const safeMaxSpeed = isNaN(maxSpeed) || maxSpeed <= 1.2 ? 1.2 : maxSpeed; 

    if (timeDifference < 500) { 
        this.speedControl.value = safeMaxSpeed; // Usa o valor seguro
        // ... (lógica de vídeo)
    } else if (timeDifference > 1000) { 
        this.speedControl.value = 1.2;
        // ... (lógica de vídeo)
    } else {
        this.speedControl.value = this.userConfiguredSpeed;
        // ... (lógica de vídeo)
    }
    this.updateRangeValue('speed');
}
```

#### Versão 10: Combinação Otimizada (Predição + Suavização)
Combina a predição (Versão 3) com a suavização (Versão 8), criando um sistema que antecipa e transiciona de forma gradual para a correção.

```javascript
adjustSynchronization(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const timeDifference = this.speechQueue[0].startTime - currentTime;
    const maxSpeed = parseFloat(this.maxSpeedControl.value);
    const currentSpeed = parseFloat(this.speedControl.value);

    let targetSpeed = this.userConfiguredSpeed;

    if (timeDifference < 1500 && timeDifference > -300) { 
        // Calcula um alvo progressivo baseado no erro
        targetSpeed = 1.2 + (Math.abs(timeDifference) / 1500) * (maxSpeed - 1.2);
    }

    // Suaviza a transição em direção ao alvo
    this.speedControl.value = currentSpeed + (targetSpeed - currentSpeed) * 0.15; 

    // ... (ajuste de vídeo)
    this.updateRangeValue('speed');
}
```

